function DecideFormulaLE(S, c, φ, ψ):
    primes = EnumeratePrimeCongruences(S, c)
    for P in primes:
        for v in Valuations(Vars(φ,ψ), S):
            if eval(φ,v) + eval(ψ,v) ≁_P eval(ψ,v):
                return (False, P, v)
